/**
 * @distilled.cloud/honeybadger -- Honeybadger v3 API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from Honeybadger's OpenAPI document
 * (https://docs.honeybadger.io/api/v3/openapi.json), mirrored at
 * `specs/spec-mirror-honeybadger/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per spec tag, imported from its subpath: `projects`, `faults`,
 * `uptime_sites`, `check_ins`, `dashboards`, `ingestion_keys`, and the rest.
 * The root exports only the shared runtime.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as Stream from "effect/Stream";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Honeybadger from "@distilled.cloud/honeybadger";
 * import * as Projects from "@distilled.cloud/honeybadger/projects";
 *
 * const program = Effect.gen(function* () {
 *   // Every project the token can reach, page by page.
 *   const projects = yield* Projects.listProjects
 *     .items({ per_page: 25 })
 *     .pipe(Stream.runCollect);
 *
 *   const first = projects[0];
 *   if (first === undefined) return { projects: 0 };
 *
 *   // One project in full.
 *   const { data: project } = yield* Projects.getProject({ project_id: first.id });
 *
 *   return {
 *     projects: projects.length,
 *     name: project.name,
 *     active: project.active,
 *   };
 * });
 *
 * const HoneybadgerLive = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Honeybadger.CredentialsFromEnv,
 *   Honeybadger.HoneybadgerProtocol,
 * );
 *
 * program.pipe(Effect.provide(HoneybadgerLive), Effect.runPromise).then(console.log);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  HoneybadgerProtocol,
  type HoneybadgerOpError,
  type HoneybadgerOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
